using Mutagen.Bethesda.Plugins;
using Mutagen.Bethesda.Plugins.Binary.Headers;
using Mutagen.Bethesda.Plugins.Meta;
using Mutagen.Bethesda.Starfield;
using Shouldly;
using Xunit;
using static Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield.StarfieldTestRecords;

namespace Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield;

// Race fields named after their signatures get xEdit's names (RegisterRecordDef(RACE)):
// WED0/WED1 are the Open Corpse and Close Corpse sounds ('Sounds made when looted'; 30 of 31 races, all 40 bytes),
// FCTP is the Face Custom Textures Base Path (3 in Starfield.esm).
// The test reads a whole race from Starfield.esm with both readers and writes it back byte for byte, leaving out the
// localized strings (FULL, DESC), which the test writer can't write back as string IDs.
public class RaceFieldNameTests
{
    private static readonly RecordType[] Localized = { new("FULL"), new("DESC") };

    private static byte[] WithoutLocalized(ReadOnlySpan<byte> content)
    {
        var ret = new MemoryStream();
        var pos = 0;
        while (pos < content.Length)
        {
            var type = new RecordType(BitConverter.ToInt32(content.Slice(pos, 4)));
            var len = BitConverter.ToUInt16(content.Slice(pos + 4, 2));
            if (!Localized.Contains(type)) ret.Write(content.Slice(pos, 6 + len));
            pos += 6 + len;
        }
        return ret.ToArray();
    }

    private static IEnumerable<IRaceGetter> Read(string hex)
        => ReadBoth<IRaceGetter>(Record("RACE", Hex(hex)), f => Race.CreateFromBinary(f), (s, p) => RaceBinaryOverlay.RaceFactory(s, p));

    // HumanCorpseRace (034FB1:Starfield.esm)
    private const string Corpse = "";

    [Fact]
    public void HumanCorpse_CorpseSoundsAndFaceTexturePath()
    {
        foreach (var race in Read(Corpse))
        {
            race.OpenCorpseSound.ShouldNotBeNull();
            race.CloseCorpseSound.ShouldNotBeNull();
            var cs = race.ChargenAndSkintones.ShouldNotBeNull();
            new[] { cs.Male, cs.Female }.Select(x => x?.FaceCustomTexturesBasePath).ShouldContain(@"actors\Corpse");
            var written = GameConstants.Starfield.MajorRecord(Write(w => race.WriteToBinary(w)));
            WithoutLocalized(written.Content).ShouldBe(WithoutLocalized(Hex(Corpse)));
        }
    }
}
